// Example Adaptive Pocket Toolpath
// Generated for PRISM Learning Engine
tool(1);                    // Tool #1
units(METRIC);              // Use millimeters
feed(1000);                 // 1000 mm/min feed
speed(12000);               // 12000 RPM spindle
rapid({z: 5});              // Rapid to safe height

// Define pocket boundary 
var pocketWidth = 50;
var pocketLength = 100;
var pocketDepth = 10;
var stepdown = 2;           // 2mm per pass
var toolDia = 10;           // 10mm endmill
var stepover = toolDia * 0.4; // 40% stepover for adaptive

// Adaptive pocket clearing
for (var z = -stepdown; z >= -pocketDepth; z -= stepdown) {
  rapid({x: 0, y: 0});
  rapid({z: z + 2});
  cut({z: z});

  // Trochoidal path pattern
  for (var y = stepover/2; y < pocketWidth; y += stepover) {
    for (var x = stepover/2; x < pocketLength; x += stepover) {
      // Arc entry and clearing pattern
      arc({x: x + toolDia/2, y: y, z: z, i: toolDia/4, j: 0}, 'cw');
      cut({x: x, y: y});
    }
    // Reverse direction for next row
    for (var x = pocketLength - stepover/2; x > 0; x -= stepover) {
      arc({x: x - toolDia/2, y: y + stepover, z: z, i: -toolDia/4, j: 0}, 'ccw');
      cut({x: x, y: y + stepover});
    }
  }
}

rapid({z: 5});

// Face Milling Operation
tool(4);                     // Face mill
units(METRIC);
feed(2000);
speed(8000);
rapid({z: 25});

var faceWidth = 150;
var faceLength = 200;
var toolDia = 50;            // 50mm face mill
var stepover = toolDia * 0.65; // 65% stepover
var stockToRemove = 2;       // 2mm stock removal
var depthPerPass = 1;

for (var z = -depthPerPass; z >= -stockToRemove; z -= depthPerPass) {
  var y = -stepover / 2;
  var direction = 1;

  while (y < faceWidth + stepover) {
    rapid({x: direction > 0 ? -toolDia/2 : faceLength + toolDia/2, y: y});
    rapid({z: z + 0.5});
    cut({z: z});
    cut({x: direction > 0 ? faceLength + toolDia/2 : -toolDia/2});

    y += stepover;
    direction *= -1; // Alternate direction
  }
}

rapid({z: 25});

// 3D Surface Roughing - Z-Level Strategy
tool(5);
units(METRIC);
feed(1500);
speed(15000);
rapid({z: 30});

var toolDia = 12;            // Ball endmill
var stepdown = 3;            // Z-level increment
var stepover = toolDia * 0.3;
var partHeight = 25;

// Simulate dome/hemisphere surface - Z-level roughing
for (var z = -stepdown; z >= -partHeight; z -= stepdown) {
  // Calculate radius at this Z level (hemisphere equation)
  var r = Math.sqrt(Math.pow(50, 2) - Math.pow(z + partHeight, 2));

  if (r > stepover) {
    // Offset contours from outside to center
    for (var offset = r; offset > 0; offset -= stepover) {
      // Arc around at this offset
      rapid({x: offset, y: 0});
      rapid({z: z + 0.5});
      cut({z: z});

      // Full circle at constant Z
      arc({x: offset, y: 0, i: -offset, j: 0, z: z}, 'ccw');
    }
  }
}

rapid({z: 30});

// Example Drilling Pattern with Peck Cycle
tool(3);
units(METRIC);
speed(3000);

var holes = [
  {x: 10, y: 10, depth: 15},
  {x: 30, y: 10, depth: 15},
  {x: 50, y: 10, depth: 15},
  {x: 10, y: 30, depth: 20},
  {x: 30, y: 30, depth: 20},
  {x: 50, y: 30, depth: 20}
];

var peckDepth = 3; // 3mm peck increment
var retract = 2;   // Retract amount per peck
var drillingFeed = 150;

for (var i = 0; i < holes.length; i++) {
  var hole = holes[i];
  rapid({x: hole.x, y: hole.y});
  rapid({z: 2});

  // Peck drilling cycle
  for (var z = -peckDepth; z >= -hole.depth; z -= peckDepth) {
    feed(drillingFeed);
    cut({z: Math.max(z, -hole.depth)});
    rapid({z: z + retract}); // Retract to clear chips
    rapid({z: z + 0.5});     // Rapid back near previous depth
  }

  rapid({z: 5});
}

var width = 25.4 * 1.9;
var length = 70.25;
var side = 59.25;
var depth = 25.4 * 0.25;


function print_point(point) {
    print('(', point[0], ', ', point[1], ')');
}


function print_poly(poly) {
    print('(');

    for (var j = 0; j < poly.length; j++) {
        if (j) print(', ');
        print_point(poly[j]);
    }

    print(')\n');
}


function arc2D(start, end) {
    var points = [];

    start = 2 * Math.PI - start;
    end = 2 * Math.PI - end;

    var steps = Math.round(Math.abs(end - start) / (Math.PI * 2 / 100)) + 1;
    var delta = (end - start) / steps;

    for (var i = 0; i < steps; i++) {
        var angle = start + delta * i;
        points.push([Math.cos(angle), Math.sin(angle)]);
    }

    return points;
}


function scale2D(points, factor) {
    var result = [];

    for (var i = 0; i < points.length; i++) {
        var point = [];

        for (var j = 0; j < points[i].length; j++)
            point.push(points[i][j] * factor[j]);

        result.push(point);
    }

    return result;
}


function translate2D(points, offset) {
    var result = [];

    for (var i = 0; i < points.length; i++) {
        var point = [];

        for (var j = 0; j < points[i].length; j++)
            point.push(points[i][j] + offset[j]);

        result.push(point);
    }

    return result;
}


function shape(width, length, side, radius) {
    var poly = [];

    poly.push([0, radius]);
    poly.push([0, side]);

    poly = poly.concat(
        translate2D(
            scale2D(arc2D(Math.PI, 2 * Math.PI), [width / 2, length - side]),
            [width / 2, side]));

    poly.push([width, radius]);

    var points = scale2D(arc2D(2 * Math.PI, 2.5 * Math.PI), [radius, radius]);
    poly = poly.concat(translate2D(points, [width - radius, radius]));

    poly.push([radius, 0]);

    var points = scale2D(arc2D(0.5 * Math.PI, Math.PI), [radius, radius]);
    poly = poly.concat(translate2D(points, [radius, radius]));

    return poly;
}


function cut_poly(poly, depth, safe) {
    if (typeof safe == 'undefined') safe = true;

    if (safe) rapid(poly[0][0], poly[0][1]);
    else cut(poly[0][0], poly[0][1]);

    cut({z: -depth});

    for (var i = 1; i < poly.length; i++)
        cut(poly[i][0], poly[i][1]);

    if (poly[0][0] != poly[poly.length -1][0] ||
        poly[0][1] != poly[poly.length -1][1])
        cut(poly[0][0], poly[0][1]);

    if (safe) rapid({z: 5});
}


function cut_polys(polys, depth, safe) {
    for (var i = 0; i < polys.length; i++)
        cut_poly(polys[i], depth, safe);
}


function cut_poly_steps(poly, depth, safe, tabs) {
    if (typeof safe == 'undefined') safe = true;
    if (typeof tabs == 'undefined') tabs = false;

    var steps = Math.ceil(depth / maxPass);
    var pass = depth / steps;

    if (safe) rapid(poly[0][0], poly[0][1]);
    else cut(poly[0][0], poly[0][1]);

    for (var step = 1; step <= steps; step++) {
        cut({z: -pass * step});

        for (var i = 1; i < poly.length; i++)
            cut(poly[i][0], poly[i][1]);

        if (poly[0][0] != poly[poly.length -1][0] ||
            poly[0][1] != poly[poly.length -1][1])
            cut(poly[0][0], poly[0][1]);
    }

    if (safe) rapid({z: 5});
}


function cut_polys_steps(polys, depth, safe) {
    for (var i = 0; i < polys.length; i++)
        cut_poly_steps(polys[i], depth, safe);
}


function pocket_poly(poly, depth, overlap) {
    if (typeof overlap == 'undefined') overlap = 0.4;

    var steps = Math.ceil(depth / maxPass);
    var pass = depth / steps;

    for (var step = 1; step <= steps; step++) {
        var pocket = offset([poly], -toolRadius);

        rapid(pocket[0][0][0], pocket[0][0][1]);

        while (pocket.length) {
            cut_polys(pocket, pass * step, false);
            pocket = offset(pocket, -toolDia + overlap);
        }
    }

    rapid({z: 5});
}


function bottom(poly, depth, wall) {
    // Inside
    pocket_poly(poly, depth - 3);

    // Rim
    cut_polys_steps(offset([poly], -toolRadius + wall / 2 + 0.0625),
                    25.4 / 4 - 1);

    // Cutout
    cut_polys_steps(offset([poly], toolRadius + wall), depth + 0.25);
}


function top(poly, depth, wall) {
    // Inside
    pocket_poly(poly, depth - 2.5);

    // Rim
    cut_polys_steps(offset([poly], toolRadius + wall / 2 - 0.0625),
                    depth - 2.5);

    // Divit
    var divit = arc2D(Math.PI, 2 * Math.PI);
    var divitWidth = 10;
    var x = width / 2;
    var y = -4;
    var z = -depth + 2.5;
    rapid(x - divitWidth / 2, y);

    for (var i = 0; i < divit.length; i++)
        cut({x: x + divitWidth / 2 * divit[i][0], z: z - divit[i][1]});

    rapid({z: 5});

    // Cutout
    cut_polys_steps(offset([poly], toolRadius + wall), depth + 0.25);
}


