// Example Contour Toolpath with Lead-in
tool(2);
units(METRIC);
feed(800);
speed(10000);
rapid({z: 10});

var contourDepth = 5;
var stepdown = 2.5;
var leadRadius = 5; // Arc lead-in radius

// Contour points (clockwise)
var contour = [
  {x: 0, y: 0},
  {x: 100, y: 0},
  {x: 100, y: 50},
  {x: 50, y: 50},
  {x: 50, y: 75},
  {x: 0, y: 75},
  {x: 0, y: 0}
];

for (var z = -stepdown; z >= -contourDepth; z -= stepdown) {
  // Arc lead-in
  rapid({x: -leadRadius, y: -leadRadius});
  rapid({z: z + 1});
  cut({z: z});
  arc({x: 0, y: 0, i: leadRadius, j: 0, z: z}, 'cw');

  // Cut contour
  for (var i = 1; i < contour.length; i++) {
    cut({x: contour[i].x, y: contour[i].y});
  }

  // Arc lead-out
  arc({x: -leadRadius, y: leadRadius, i: -leadRadius, j: 0}, 'cw');
}

rapid({z: 10});

